INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_couples', 'Educators call this the cardinal privacy rule of sexting.', 'never share or forward without consent', ARRAY['never share without consent', 'don''t share it', 'never forward', 'don''t forward without permission', 'keep it private', 'never screenshot or share', 'don''t share without permission']::text[], 1, 'Never share without consent — what''s sent to you isn''t yours to forward. Full stop.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_couples', 'A 2017 study found the bonded, satisfied afterglow following sex lasts about this long.', 'about forty-eight hours', ARRAY['48 hours', 'forty eight hours', 'forty-eight hours', 'two days', 'about two days', '48', 'about 48 hours']::text[], 2, 'About forty-eight hours — a two-day glow that the study linked to longer-term relationship satisfaction.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The letters in BDSM stand for this.', 'Bondage, discipline, dominance, submission, sadism, and masochism', ARRAY['bondage discipline dominance submission sadism masochism', 'bondage and discipline dominance and submission sadism and masochism', 'bondage discipline sadism masochism', 'bondage discipline sadomasochism']::text[], 1, 'Six words packed into four letters — an overlapping umbrella, and every corner of it runs on negotiated consent.', true, 'active', 'principal_adult_v1', ARRAY['Bondage, discipline, dominance, submission, sadism, and masochism', 'Bondage, domination, service, and mercy', 'Blindfolds, dungeons, spanking, and more', 'Bedroom drama, seriously managed']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The classic kink safety motto SSC stands for these three words.', 'safe, sane, and consensual', ARRAY['safe sane consensual', 'safe sane and consensual']::text[], 2, 'Safe, sane, consensual — the older motto; RACK, risk-aware consensual kink, is its franker modern sibling.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What is this many-tailed impact toy called?', 'a flogger', ARRAY['flogger', 'a flogger', 'the flogger']::text[], 2, 'A flogger — many soft tails spread the impact into a thuddy sensation. Aim for muscle, never the spine or kidneys.', true, 'active', 'principal_adult_v1', NULL, 'Artistic close-up photo of a black leather flogger with multiple suede tails laid on a dark velvet background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Sadism takes its name from this notorious French aristocrat and writer.', 'the Marquis de Sade', ARRAY['marquis de sade', 'the marquis de sade', 'de sade', 'sade']::text[], 2, 'The Marquis de Sade — the clinical term came later, coined by psychiatrist Krafft-Ebing. Modern sadism, unlike the Marquis, requires enthusiastic consent.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'A safe word exists so that a partner can do this.', 'Stop or slow the scene immediately', ARRAY['stop the scene', 'stop immediately', 'stop or slow the scene', 'stop everything', 'call it off', 'end the scene']::text[], 1, 'Instant stop or check-in — many players use traffic lights: red for stop, yellow for check in, green for keep going.', true, 'active', 'principal_adult_v1', ARRAY['Ask for more intensity', 'Stop or slow the scene immediately', 'Signal that aftercare is over', 'Use a cute nickname']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The cuddling, water, and conversation that follow an intense scene are collectively called this.', 'aftercare', ARRAY['aftercare', 'after care']::text[], 2, 'Aftercare — it cushions the endorphin comedown for subs and doms alike. Skipping it is how drop happens.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What is this intricate Japanese art of decorative rope bondage called?', 'shibari', ARRAY['shibari', 'kinbaku', 'japanese rope bondage']::text[], 3, 'Shibari — also called kinbaku. Riggers keep safety shears within reach and check hands for numbness constantly.', true, 'active', 'principal_adult_v1', NULL, 'Artistic black-and-white photograph of intricate red rope shibari patterns tied on a person''s arms and torso, elegant consensual aesthetic, soft lighting');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Impact players contrast a heavy flogger''s deep sensation with a cane''s sharp one using this pair of terms.', 'Thuddy versus stingy', ARRAY['thuddy and stingy', 'thuddy versus stingy', 'thuddy stingy', 'thuddy vs stingy']::text[], 3, 'Thuddy versus stingy — deep bass versus sharp treble. Most players strongly prefer one; negotiate which before swinging anything.', true, 'active', 'principal_adult_v1', ARRAY['Thuddy versus stingy', 'Blunt versus bright', 'Bassy versus trebly', 'Rare versus well-done']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Someone who takes consensual pleasure in delivering pain or humiliation in a scene is called this.', 'a sadist', ARRAY['sadist', 'a sadist', 'sadistic top', 'a dominant sadist', 'the sadist']::text[], 2, 'A sadist — in kink, always paired with a willing masochist or submissive. The consent is what separates a scene from a crime.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Pre-negotiated scenes in which partners role-play resistance are known by this three-letter abbreviation.', 'CNC', ARRAY['cnc', 'consensual non-consent', 'consensual nonconsent', 'consensual non consent']::text[], 3, 'CNC, consensual non-consent — scripted in advance, bounded by safe words, and built on the deepest trust in the toolbox. The consent is real even when the script pretends otherwise.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The kink-safety acronym RACK stands for this.', 'Risk-aware consensual kink', ARRAY['risk aware consensual kink', 'risk-aware consensual kink']::text[], 2, 'Risk-aware consensual kink — an honest admission that nothing is perfectly safe, so informed adults weigh the risks together.', true, 'active', 'principal_adult_v1', ARRAY['Risk-aware consensual kink', 'Rules about consensual kink', 'Really ambitious cool kink', 'Restraints and careful knots']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The floaty, euphoric endorphin state a submissive can enter during an intense scene is called this.', 'subspace', ARRAY['subspace', 'sub space']::text[], 3, 'Subspace — a genuine altered state. Someone deep in it can''t reliably consent to new things, which is why terms get negotiated before the scene, never during.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What are these adjustable pinching devices called?', 'nipple clamps', ARRAY['nipple clamps', 'clamps', 'nipple clamp']::text[], 2, 'Nipple clamps — the real intensity spike arrives when they come off and the blood rushes back. Time-limit them.', true, 'active', 'principal_adult_v1', NULL, 'Artistic close-up photo of adjustable metal nipple clamps on a black velvet background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In kink, the abbreviation CBT stands for this — and it is not cognitive behavioral therapy.', 'cock and ball torture', ARRAY['cock and ball torture', 'cock and ball play', 'genital pain play', 'ball torture']::text[], 3, 'Cock and ball torture — consensual genital pain play, negotiated in fine detail beforehand. The other CBT can help you process it.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Humiliation play, done right, involves this.', 'Consensual erotic embarrassment negotiated in advance', ARRAY['consensual erotic embarrassment', 'negotiated embarrassment', 'consensual degradation', 'consensual embarrassment agreed in advance']::text[], 3, 'Negotiated erotic embarrassment — the words and themes are agreed beforehand, and real insecurities stay strictly off the menu unless explicitly invited.', true, 'active', 'principal_adult_v1', ARRAY['Consensual erotic embarrassment negotiated in advance', 'Genuinely insulting your partner''s cooking', 'Degrading someone without asking first', 'Publicly shaming strangers']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What is this flat-impact classic called?', 'a paddle', ARRAY['paddle', 'a paddle', 'the paddle', 'spanking paddle']::text[], 2, 'A paddle — broad, thuddy, and beginner-friendly. Stick to the fleshy lower cheeks and avoid the tailbone.', true, 'active', 'principal_adult_v1', NULL, 'Close-up photo of a leather spanking paddle on a dark background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Dripping candle wax on a partner for temperature sensation is simply called this.', 'wax play', ARRAY['wax play', 'waxplay', 'candle wax play', 'candle play']::text[], 2, 'Wax play — use low-temperature soy or paraffin candles made for skin; regular candles, especially beeswax, burn far hotter. Test on your own wrist first, and keep cool water nearby.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In kink, a switch is this.', 'A person who enjoys both dominant and submissive roles', ARRAY['someone who enjoys both roles', 'both dominant and submissive', 'enjoys both roles', 'plays both roles', 'someone who can dom or sub']::text[], 1, 'Someone who plays both sides of the slash — dominant one scene, submissive the next, depending on partner and mood.', true, 'active', 'principal_adult_v1', ARRAY['A person who enjoys both dominant and submissive roles', 'A light-controlling wall fixture', 'A thin, springy cane', 'Someone who swaps partners mid-scene']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What is this rigid restraint called?', 'a spreader bar', ARRAY['spreader bar', 'a spreader bar', 'spreader', 'the spreader bar']::text[], 2, 'A spreader bar — keeps limbs fixed apart. Like all restraints: never on an unattended partner, and quick-release beats padlocks.', true, 'active', 'principal_adult_v1', NULL, 'Artistic photo of a metal spreader bar with padded cuffs on black silk, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The emotional crash that can hit a submissive hours or even days after a scene is called this.', 'sub drop', ARRAY['sub drop', 'subdrop', 'drop', 'the drop']::text[], 3, 'Sub drop — the endorphin bill arriving late. Planned aftercare, hydration, snacks, and a next-day check-in are the standard prevention kit. Doms drop too.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What is this strapped, mouth-filling item called?', 'a ball gag', ARRAY['ball gag', 'a ball gag', 'ballgag', 'gag', 'a gag']::text[], 2, 'A ball gag — since it takes away the safe word, gagged partners hold something to drop, or use hand signals instead.', true, 'active', 'principal_adult_v1', NULL, 'Artistic product photo of a black leather ball gag with a silicone ball on a dark background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Taking away sight with a blindfold works in play mainly because it does this.', 'Heightens the other senses and the anticipation', ARRAY['heightens the other senses', 'sharpens the other senses', 'builds anticipation', 'heightens anticipation', 'makes every touch a surprise']::text[], 1, 'Every remaining sense turns up — touch, sound, suspense. Agree on verbal check-ins first, since the wearer can''t read your face.', true, 'active', 'principal_adult_v1', ARRAY['Heightens the other senses and the anticipation', 'Helps the wearer nap between rounds', 'Improves long-term vision', 'Is required by dungeon law']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Delivering the sharpest sting in the impact family, what is this thin rod called?', 'a cane', ARRAY['cane', 'a cane', 'the cane', 'rattan cane']::text[], 3, 'The cane — maximum sting, serious marks, advanced-level toy. Fleshy areas only; never over the kidneys, spine, or joints.', true, 'active', 'principal_adult_v1', NULL, 'Artistic photo of a thin rattan cane on a dark velvet background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'A violet wand delivers its signature play sensation using this.', 'static electricity', ARRAY['static electricity', 'electricity', 'electric sparks', 'static sparks', 'electrostatic sparks', 'static']::text[], 3, 'Crackling static-style sparks — genuine electro play. Keep it away from the head and heart, and off-limits entirely for anyone with a pacemaker or similar implant.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The Wartenberg wheel, that spiked pinwheel in sensation kits, was originally invented for this.', 'Testing nerve responses in neurology exams', ARRAY['testing nerve responses', 'neurology', 'nerve testing', 'a medical device', 'testing reflexes', 'neurological exams']::text[], 2, 'A neurologist''s nerve-testing tool — Dr. Robert Wartenberg would be surprised where his wheel rolled. Run it lightly; it''s sharper than it looks.', true, 'active', 'principal_adult_v1', ARRAY['Testing nerve responses in neurology exams', 'Cutting pizza', 'Marking fabric for tailors', 'Medieval torture']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In D/s relationships, wearing this piece of neckwear often symbolizes commitment or belonging.', 'a collar', ARRAY['collar', 'a collar', 'the collar']::text[], 2, 'The collar — some communities hold collaring ceremonies with the weight of engagements. Never touch or remove someone else''s without invitation.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'What is this lockable item, central to orgasm-denial dynamics, called?', 'a chastity cage', ARRAY['chastity cage', 'a chastity cage', 'chastity device', 'cage', 'cock cage', 'chastity belt', 'a chastity device']::text[], 2, 'A chastity cage — the keyholder dynamic runs on trust and a spare emergency key. Proper fit matters; numbness or swelling means off, now.', true, 'active', 'principal_adult_v1', NULL, 'Product-style photo of a polycarbonate chastity cage device with a small padlock on a neutral background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Pet play involves this.', 'Consensually role-playing an animal persona like a kitten or pup', ARRAY['role-playing an animal persona', 'roleplaying as an animal', 'acting like a kitten or puppy', 'animal roleplay', 'consensual animal roleplay']::text[], 2, 'Human pets, human handlers — kittens, pups, and ponies with ears, tails, and headspace. Your actual cat remains unimpressed.', true, 'active', 'principal_adult_v1', ARRAY['Consensually role-playing an animal persona like a kitten or pup', 'Bringing your actual cat into the bedroom', 'Role-playing as a veterinarian', 'Developing a fur allergy']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Safety educators single out breath play as uniquely dangerous because its central risk is this.', 'it can never be made fully safe', ARRAY['it can''t be made safe', 'it can never be made safe', 'no safe way to do it', 'risk of cardiac arrest', 'it can kill without warning', 'you can''t eliminate the risk', 'oxygen deprivation can cause sudden death', 'there''s no safe way']::text[], 3, 'There is no known technique that removes the danger — restricting oxygen can trigger cardiac arrest or lasting injury in seconds, with no warning signs. Many educators simply say don''t; the rest say know exactly what you''re risking.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Practitioners of fire play never begin without this piece of safety equipment within arm''s reach.', 'a fire extinguisher', ARRAY['fire extinguisher', 'a fire extinguisher', 'extinguisher', 'damp towel', 'a wet towel', 'wet towels', 'fire blanket', 'a fire blanket']::text[], 3, 'An extinguisher, damp towels, or a fire blanket — fire play is expert-level edge play, learned in person from experienced practitioners, never from a video.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In needle play, the one absolutely non-negotiable equipment rule is this.', 'sterile, single-use needles only', ARRAY['sterile needles', 'single use needles', 'sterile single-use needles', 'never reuse needles', 'new needles every time', 'sterile single use needles only']::text[], 3, 'Sterile and single-use, with a proper sharps container for disposal — bloodborne-pathogen safety is the entire ballgame in any play that breaks skin.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Figging, a practice kink lore traces back centuries, involves this root.', 'Ginger', ARRAY['ginger', 'ginger root']::text[], 3, 'Ginger — peeled and used for its escalating burn. The lore traces it to Victorian discipline and even older horse-trading tricks; the burn, at least, is entirely real.', true, 'active', 'principal_adult_v1', ARRAY['Ginger', 'Ginseng', 'Wasabi', 'Turmeric']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Deliberately halting all stimulation at the exact point of no return produces this frustrating specialty.', 'a ruined orgasm', ARRAY['ruined orgasm', 'a ruined orgasm', 'ruining', 'ruined']::text[], 3, 'The ruined orgasm — climax arrives but the pleasure is deliberately sabotaged. A tease-and-denial classic, negotiated like everything else.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In negotiated play, continuing stimulation relentlessly through and past climax is called this.', 'a forced orgasm', ARRAY['forced orgasm', 'a forced orgasm', 'forced orgasms']::text[], 3, 'The forced orgasm — the force is the fantasy; the consent is negotiated in advance and revocable at a word. Overstimulation is intense, so safe words stay live throughout.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Which statement correctly separates subspace from sub drop?', 'Subspace is the euphoric high during a scene; sub drop is the crash afterward', ARRAY['subspace is during and drop is after', 'subspace is the high sub drop is the crash', 'the high during versus the crash after', 'subspace is the high during the scene and sub drop is the crash afterward']::text[], 2, 'The high during, the crash after — two ends of the same endorphin arc, and aftercare is the bridge between them.', true, 'active', 'principal_adult_v1', ARRAY['Subspace is the euphoric high during a scene; sub drop is the crash afterward', 'Sub drop happens during; subspace comes after', 'They''re both types of dungeon furniture', 'They''re two names for the same thing']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In negotiation, the difference between a hard limit and a soft limit is this.', 'a hard limit is an absolute never; a soft limit is a maybe, with caution', ARRAY['hard is never soft is maybe', 'hard limits are absolute', 'a hard limit is a no a soft limit is a maybe', 'never versus maybe', 'absolute no versus approach with caution', 'hard means never soft means maybe']::text[], 2, 'Hard means never, full stop, not up for discussion; soft means maybe, carefully, under the right conditions. Both get written down before anyone gets tied down.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'A low-pressure kink community meetup held in street clothes at a cafe or restaurant is called this.', 'a munch', ARRAY['munch', 'a munch', 'munches', 'the munch']::text[], 2, 'A munch — how newcomers meet the community safely: public venue, regular clothes, no play, just people vetting people.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'At any dungeon or play party, the universal etiquette rule about other people''s gear, toys, and partners is this.', 'never touch without asking', ARRAY['never touch without asking', 'ask first', 'don''t touch without permission', 'always ask permission', 'hands off unless invited', 'ask before touching']::text[], 2, 'Ask first, always — and never interrupt a running scene. Dungeon monitors exist precisely to enforce both.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Dense and heavy like this one, a rubber flogger delivers which of the two classic impact sensations?', 'thuddy', ARRAY['thuddy', 'thud', 'thuddy sensation', 'the thuddy one']::text[], 2, 'Thuddy — deep, muscle-level impact, the bass note of impact play. Thin and fast means stingy; thick and heavy means thuddy.', true, 'active', 'principal_adult_v1', NULL, 'Artistic photo of a heavy black rubber flogger with thick wide tails on a dark background, educational style');
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Educators steer bondage beginners toward cuffs instead of rope for this reason.', 'Cuffs release quickly and are harder to over-tighten', ARRAY['they release quickly', 'quicker to release', 'harder to over-tighten', 'safer and faster to remove', 'quick release', 'they come off fast and don''t over-tighten']::text[], 2, 'Quick release, no accidental tightening, no nerve-pinching knots — and whichever you choose, safety shears live within reach, always.', true, 'active', 'principal_adult_v1', ARRAY['Cuffs release quickly and are harder to over-tighten', 'Rope is illegal in most cities', 'Cows demand representation', 'Rope only comes in beige']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Many committed M/s couples negotiate this document, spelling out duties, limits, and review dates.', 'a contract', ARRAY['contract', 'a contract', 'a slave contract', 'an agreement', 'a written agreement']::text[], 3, 'A contract — not legally binding anywhere, but a serious negotiation artifact, revisited and revised as the dynamic evolves. Consent is ongoing; it can''t be signed away.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'A dynamic where dominance and submission continue beyond scenes into everyday life is known by this around-the-clock name.', 'twenty-four seven', ARRAY['24/7', 'twenty four seven', 'twenty-four seven', '24 7', 'total power exchange', 'tpe', '24/7 power exchange']::text[], 3, 'Twenty-four-seven, or total power exchange — the lifestyle end of the spectrum. Even here consent stays revocable; that''s what keeps it kink and not captivity.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Bombarding a partner with wax, ice, vibration, and sound all at once is a technique called this.', 'sensory overload', ARRAY['sensory overload', 'overstimulation', 'sensation overload', 'overload']::text[], 2, 'Sensory overload — the opposite of deprivation, and often paired with it. When the nervous system maxes out, the safe word matters more, not less.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Before any humiliation play begins, this specific conversation is considered mandatory.', 'negotiating which words and themes are off-limits', ARRAY['negotiating limits', 'agreeing what''s off-limits', 'negotiating boundaries', 'discussing off-limits words', 'negotiation', 'what words are banned', 'setting off-limits words and themes']::text[], 2, 'The off-limits list — which words, which themes, which real insecurities are untouchable. Degradation is a performance the two of you script; it should never be a review.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'In kink vocabulary, edge play refers to this.', 'High-risk activities like knife or breath play requiring expert care', ARRAY['high-risk activities', 'high risk play', 'high-risk kink', 'dangerous kink activities', 'play with real risk', 'the high-risk stuff']::text[], 3, 'The high-risk tier — knife, fire, breath, blood. Not the same as edging, despite the name. Strictly risk-aware territory: research, mentorship, and brutal honesty about the dangers.', true, 'active', 'principal_adult_v1', ARRAY['High-risk activities like knife or breath play requiring expert care', 'Sex on the edge of the bed', 'Another word for edging', 'Playing guitar like the guy from U2']::text[], NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'The kink-ethics acronym PRICK stands for this.', 'personal responsibility, informed, consensual kink', ARRAY['personal responsibility informed consensual kink', 'personal responsibility in consensual kink']::text[], 3, 'Personal Responsibility, Informed, Consensual Kink — SSC''s and RACK''s younger sibling, putting each player''s own accountability at the center.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Name three items commonly packed in an aftercare kit.', 'water, a blanket, and snacks', ARRAY['water', 'blanket', 'a blanket', 'snacks', 'chocolate', 'juice', 'lotion', 'arnica', 'wipes', 'a sweater', 'electrolytes', 'comfort items', 'a stuffed animal']::text[], 1, 'Water, blanket, snacks — plus lotion, arnica for bruises, and whatever comfort object works. Hydration and warmth first; endorphin crashes are physical events.', true, 'active', 'principal_adult_v1', NULL, NULL);
INSERT INTO lily_questions (mode, category, question, canonical_answer, acceptable_answers, difficulty_tier, reveal_color, adult, status, source, choices, image_prompt) VALUES ('adult', 'adult_kink', 'Masochism takes its name from Leopold von Sacher-Masoch, the Austrian author of this fur-draped 1870 novella.', 'Venus in Furs', ARRAY['venus in furs', 'venus in fur']::text[], 3, 'Venus in Furs — Krafft-Ebing borrowed the author''s name for the term, reportedly to Sacher-Masoch''s dismay. The Velvet Underground borrowed the title a century later.', true, 'active', 'principal_adult_v1', NULL, NULL);
